const totals = new Map();
for (const { userId, amount } of orders) {
  totals.set(userId, (totals.get(userId) ?? 0) + amount);
}
return [...totals].map(([userId, total]) => ({ userId, total }))
  .toSorted((a, b) => b.total - a.total);
```
O(n + k log k), using a Map so user ids of any type work.

